window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-c9c077c06751e7e5"]={"versions": [{"id": "FIG-c9c077c06751e7e5", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm (<code>sd Dev Error Tracer</code>) zur Spezifikation des Fehlerbehandlungs- und Meldeverhaltens bei Entwicklungsfehlern (Development Errors) im AUTOSAR-CAN-Transport-Layer (<code>CanTp</code>). Das Diagramm illustriert das Interaktionsmuster zwischen einem generischen Aufrufer, dem BSW-Modul <code>CanTp</code> und dem zentralen Diagnosedienst <code>Development Error Tracer</code> (DET).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Instanzen und Komponenten (Lifelines):</p>\n<ul class=\"fig-list\">\n<li><code>Caller</code>: Generisches Aufrufermodul (z. B. PDU Router / Pdur oder BSW-Manager).</li>\n<li><code>CanTp</code>: CAN Transport Layer Modul der AUTOSAR Classic Platform.</li>\n<li><code>Development Error Tracer</code>: Zentrales Modul zur Protokollierung von Entwicklungsfehlern (DET).</li>\n</ul>\n<p class=\"fig-p\">Schnittstellen und Nachrichten:</p>\n<ul class=\"fig-list\">\n<li><code>API call with wrong parameters</code>: Generischer synchroner Aufruf einer CanTp-Schnittstelle mit ungültigen Parametern.</li>\n<li><code>Det_ReportError(ModuleId, InstanceId, ApiId, ErrorId)</code>: Synchrone Fehlermeldung an den DET mit Angabe der Modulkennung, Instanzkennung, API-Funktionskennung und Fehlerkennung.</li>\n<li>Rückgabewerte:</li>\n<li><code>E_NOT_OK</code>: Fehlerhafter Ausführungsstatus vom Typ <code>Std_ReturnType</code> an den Aufrufer.</li>\n<li><code>E_OK</code>: Erfolgreicher Ausführungsstatus vom Typ <code>Std_ReturnType</code> an den Aufrufer.</li>\n<li><code>API call with good parameters</code>: Generischer synchroner Aufruf einer CanTp-Schnittstelle mit validen Parametern.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Ablauf ist in einem kombinierten Fragment (<code>alt</code>) strukturiert:</p>\n<ol class=\"fig-list\">\n<li>Zweig <code>[A development error occurs]</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der <code>Caller</code> setzt einen synchronen Aufruf mit ungültigen Parametern an <code>CanTp</code> ab.</li>\n<li><code>CanTp</code> detektiert den Parameterfehler und ruft synchron die Funktion <code>Det_ReportError(ModuleId, InstanceId, ApiId, ErrorId)</code> am <code>Development Error Tracer</code> auf.</li>\n<li>Nach der Rückkehr aus <code>Det_ReportError</code> antwortet <code>CanTp</code> dem <code>Caller</code> mit dem Fehlerwert <code>E_NOT_OK</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Zweig <code>[No development error]</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der <code>Caller</code> setzt einen synchronen Aufruf mit korrekten Parametern an <code>CanTp</code> ab.</li>\n<li>Es erfolgt kein Aufruf des <code>Development Error Tracer</code>.</li>\n<li><code>CanTp</code> quittiert den Aufruf gegenüber dem <code>Caller</code> direkt mit <code>E_OK</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normatives Standard-Fehlermeldemuster für AUTOSAR-BSW-Module: Bei aktivierter Entwicklungsfehler-Erkennung (<code>CanTpDevErrorDetect = TRUE</code>) müssen API-Parameterprüfungen vor der Funktionsausführung erfolgen. Im Fehlerfall ist zwingend <code>Det_ReportError</code> mit den entsprechenden Modul- und Kontext-IDs aufzurufen, die Verarbeitung vorzeitig abzubrechen und der Rückgabewert <code>E_NOT_OK</code> zurückzugeben. Bei fehlerfreiem Aufruf erfolgt die reguläre Bearbeitung mit dem Rückgabewert <code>E_OK</code>.</p>"}, {"id": "FIG-a2afc7c85a98e884", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm (<code>sd Dev Error Tracer</code>) zur Spezifikation des Fehlerbehandlungs- und Meldeverhaltens bei Entwicklungsfehlern (Development Errors) im AUTOSAR-CAN-Transport-Layer (<code>CanTp</code>). Das Diagramm illustriert das Interaktionsmuster zwischen einem generischen Aufrufer, dem BSW-Modul <code>CanTp</code> und dem zentralen Diagnosedienst <code>Development Error Tracer</code> (DET).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Instanzen und Komponenten (Lifelines):</p>\n<ul class=\"fig-list\">\n<li><code>Caller</code>: Generisches Aufrufermodul (z. B. PDU Router / Pdur oder BSW-Manager).</li>\n<li><code>CanTp</code>: CAN Transport Layer Modul der AUTOSAR Classic Platform.</li>\n<li><code>Development Error Tracer</code>: Zentrales Modul zur Protokollierung von Entwicklungsfehlern (DET).</li>\n</ul>\n<p class=\"fig-p\">Schnittstellen und Nachrichten:</p>\n<ul class=\"fig-list\">\n<li><code>API call with wrong parameters</code>: Generischer synchroner Aufruf einer CanTp-Schnittstelle mit ungültigen Parametern.</li>\n<li><code>Det_ReportError(ModuleId, InstanceId, ApiId, ErrorId)</code>: Synchrone Fehlermeldung an den DET mit Angabe der Modulkennung, Instanzkennung, API-Funktionskennung und Fehlerkennung.</li>\n<li>Rückgabewerte:</li>\n<li><code>E_NOT_OK</code>: Fehlerhafter Ausführungsstatus vom Typ <code>Std_ReturnType</code> an den Aufrufer.</li>\n<li><code>E_OK</code>: Erfolgreicher Ausführungsstatus vom Typ <code>Std_ReturnType</code> an den Aufrufer.</li>\n<li><code>API call with good parameters</code>: Generischer synchroner Aufruf einer CanTp-Schnittstelle mit validen Parametern.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Ablauf ist in einem kombinierten Fragment (<code>alt</code>) strukturiert:</p>\n<ol class=\"fig-list\">\n<li>Zweig <code>[A development error occurs]</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der <code>Caller</code> setzt einen synchronen Aufruf mit ungültigen Parametern an <code>CanTp</code> ab.</li>\n<li><code>CanTp</code> detektiert den Parameterfehler und ruft synchron die Funktion <code>Det_ReportError(ModuleId, InstanceId, ApiId, ErrorId)</code> am <code>Development Error Tracer</code> auf.</li>\n<li>Nach der Rückkehr aus <code>Det_ReportError</code> antwortet <code>CanTp</code> dem <code>Caller</code> mit dem Fehlerwert <code>E_NOT_OK</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Zweig <code>[No development error]</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der <code>Caller</code> setzt einen synchronen Aufruf mit korrekten Parametern an <code>CanTp</code> ab.</li>\n<li>Es erfolgt kein Aufruf des <code>Development Error Tracer</code>.</li>\n<li><code>CanTp</code> quittiert den Aufruf gegenüber dem <code>Caller</code> direkt mit <code>E_OK</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normatives Standard-Fehlermeldemuster für AUTOSAR-BSW-Module: Bei aktivierter Entwicklungsfehler-Erkennung (<code>CanTpDevErrorDetect = TRUE</code>) müssen API-Parameterprüfungen vor der Funktionsausführung erfolgen. Im Fehlerfall ist zwingend <code>Det_ReportError</code> mit den entsprechenden Modul- und Kontext-IDs aufzurufen, die Verarbeitung vorzeitig abzubrechen und der Rückgabewert <code>E_NOT_OK</code> zurückzugeben. Bei fehlerfreiem Aufruf erfolgt die reguläre Bearbeitung mit dem Rückgabewert <code>E_OK</code>.</p>"}, {"id": "FIG-cf146a678b99e1fe", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm (<code>sd Dev Error Tracer</code>) zur Spezifikation des Fehlerbehandlungs- und Meldeverhaltens bei Entwicklungsfehlern (Development Errors) im AUTOSAR-CAN-Transport-Layer (<code>CanTp</code>). Das Diagramm illustriert das Interaktionsmuster zwischen einem generischen Aufrufer, dem BSW-Modul <code>CanTp</code> und dem zentralen Diagnosedienst <code>Development Error Tracer</code> (DET).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Instanzen und Komponenten (Lifelines):</p>\n<ul class=\"fig-list\">\n<li><code>Caller</code>: Generisches Aufrufermodul (z. B. PDU Router / Pdur oder BSW-Manager).</li>\n<li><code>CanTp</code>: CAN Transport Layer Modul der AUTOSAR Classic Platform.</li>\n<li><code>Development Error Tracer</code>: Zentrales Modul zur Protokollierung von Entwicklungsfehlern (DET).</li>\n</ul>\n<p class=\"fig-p\">Schnittstellen und Nachrichten:</p>\n<ul class=\"fig-list\">\n<li><code>API call with wrong parameters</code>: Generischer synchroner Aufruf einer CanTp-Schnittstelle mit ungültigen Parametern.</li>\n<li><code>Det_ReportError(ModuleId, InstanceId, ApiId, ErrorId)</code>: Synchrone Fehlermeldung an den DET mit Angabe der Modulkennung, Instanzkennung, API-Funktionskennung und Fehlerkennung.</li>\n<li>Rückgabewerte:</li>\n<li><code>E_NOT_OK</code>: Fehlerhafter Ausführungsstatus vom Typ <code>Std_ReturnType</code> an den Aufrufer.</li>\n<li><code>E_OK</code>: Erfolgreicher Ausführungsstatus vom Typ <code>Std_ReturnType</code> an den Aufrufer.</li>\n<li><code>API call with good parameters</code>: Generischer synchroner Aufruf einer CanTp-Schnittstelle mit validen Parametern.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Ablauf ist in einem kombinierten Fragment (<code>alt</code>) strukturiert:</p>\n<ol class=\"fig-list\">\n<li>Zweig <code>[A development error occurs]</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der <code>Caller</code> setzt einen synchronen Aufruf mit ungültigen Parametern an <code>CanTp</code> ab.</li>\n<li><code>CanTp</code> detektiert den Parameterfehler und ruft synchron die Funktion <code>Det_ReportError(ModuleId, InstanceId, ApiId, ErrorId)</code> am <code>Development Error Tracer</code> auf.</li>\n<li>Nach der Rückkehr aus <code>Det_ReportError</code> antwortet <code>CanTp</code> dem <code>Caller</code> mit dem Fehlerwert <code>E_NOT_OK</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Zweig <code>[No development error]</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der <code>Caller</code> setzt einen synchronen Aufruf mit korrekten Parametern an <code>CanTp</code> ab.</li>\n<li>Es erfolgt kein Aufruf des <code>Development Error Tracer</code>.</li>\n<li><code>CanTp</code> quittiert den Aufruf gegenüber dem <code>Caller</code> direkt mit <code>E_OK</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normatives Standard-Fehlermeldemuster für AUTOSAR-BSW-Module: Bei aktivierter Entwicklungsfehler-Erkennung (<code>CanTpDevErrorDetect = TRUE</code>) müssen API-Parameterprüfungen vor der Funktionsausführung erfolgen. Im Fehlerfall ist zwingend <code>Det_ReportError</code> mit den entsprechenden Modul- und Kontext-IDs aufzurufen, die Verarbeitung vorzeitig abzubrechen und der Rückgabewert <code>E_NOT_OK</code> zurückzugeben. Bei fehlerfreiem Aufruf erfolgt die reguläre Bearbeitung mit dem Rückgabewert <code>E_OK</code>.</p>"}], "trans": [{"from": "FIG-c9c077c06751e7e5", "to": "FIG-a2afc7c85a98e884", "fr": "R2.1.20", "tr": "R3.0.7", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-a2afc7c85a98e884", "to": "FIG-cf146a678b99e1fe", "fr": "R3.1.5", "tr": "R3.2.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
